import sys

def overlap(x, y):
    s = y + '#' + x
    pi = [0] * len(s)
    for i in range(1, len(s)):
        k = pi[i - 1]
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    return pi[-1]

def main():
    a, b = sys.stdin.read().split()[:2]
    k1 = overlap(a, b)
    k2 = overlap(b, a)
    if k2 > k1:
        print(b + a[k2:])
    else:
        print(a + b[k1:])

main()

